package com.bank.latedata.store;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Replay-safe store: window result keyed by (account|window) → overwrite, never duplicate.
public class IdempotentStore {
    private static final Logger log = Logger.getLogger(IdempotentStore.class.getName());
    private final Map<String, BigDecimal> results = new LinkedHashMap<>();

    public void put(String account, long windowStart, BigDecimal total) {
        String key = account + "|" + windowStart;
        results.put(key, total); // idempotent upsert
        log.info(() -> "STORE " + key + " = " + total);
    }
    public int size() { return results.size(); }
}
