package com.bank.latedata.window;

import com.bank.latedata.model.CardEvent;
import com.bank.latedata.store.IdempotentStore;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Event-time windowing with a watermark and allowed lateness.
public class EventTimeWindower {
    private static final Logger log = Logger.getLogger(EventTimeWindower.class.getName());
    private final long windowSizeSec;
    private final long latenessBoundSec;   // for watermark
    private final long allowedLatenessSec; // grace after watermark
    private final IdempotentStore store;

    // account|windowStart → running total
    private final Map<String, BigDecimal> openWindows = new LinkedHashMap<>();
    private final Set<String> finalized = new HashSet<>();
    private long watermark = Long.MIN_VALUE;
    private long maxSeenTime = Long.MIN_VALUE;

    public EventTimeWindower(long windowSizeSec, long latenessBoundSec,
                             long allowedLatenessSec, IdempotentStore store) {
        this.windowSizeSec = windowSizeSec;
        this.latenessBoundSec = latenessBoundSec;
        this.allowedLatenessSec = allowedLatenessSec;
        this.store = store;
    }

    public void process(CardEvent e) {
        long windowStart = (e.getEventTimeSec() / windowSizeSec) * windowSizeSec;
        long windowEnd = windowStart + windowSizeSec;
        String key = e.getAccountId() + "|" + windowStart;

        // Advance watermark using event-time, not arrival order.
        maxSeenTime = Math.max(maxSeenTime, e.getEventTimeSec());
        watermark = maxSeenTime - latenessBoundSec;

        boolean windowClosed = finalized.contains(key);
        boolean tooLate = watermark > windowEnd + allowedLatenessSec;

        if (windowClosed && tooLate) {
            log.warning(() -> "DROPPED very-late event " + e.getEventId()
                    + " (event-time " + e.getEventTimeSec() + ", watermark " + watermark + ")");
            return;
        }

        openWindows.merge(key, e.getAmount(), BigDecimal::add);
        log.info(() -> "WINDOW[" + windowStart + "-" + windowEnd + "] " + e.getAccountId()
                + " += " + e.getAmount() + " (eventId " + e.getEventId() + ", watermark " + watermark + ")");

        // Finalize windows the watermark has passed.
        if (watermark >= windowEnd && !windowClosed) {
            store.put(e.getAccountId(), windowStart, openWindows.get(key));
            finalized.add(key);
        }
    }

    // Flush any still-open windows at end of stream.
    public void flush() {
        for (Map.Entry<String, BigDecimal> en : openWindows.entrySet()) {
            if (!finalized.contains(en.getKey())) {
                String[] parts = en.getKey().split("\\|");
                store.put(parts[0], Long.parseLong(parts[1]), en.getValue());
                finalized.add(en.getKey());
            }
        }
    }
}
