package com.bank.latedata;

import com.bank.latedata.model.CardEvent;
import com.bank.latedata.store.IdempotentStore;
import com.bank.latedata.window.EventTimeWindower;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class LateDataDemo {
    private static final Logger log = Logger.getLogger(LateDataDemo.class.getName());

    public static void main(String[] args) {
        IdempotentStore store = new IdempotentStore();

        // Events arrive OUT OF ORDER by event-time (60s windows, 5s watermark lag, 30s lateness).
        List<CardEvent> arrival = List.of(
            new CardEvent("E1", "SAV2001", new BigDecimal("1200"), 30),   // window 0-60
            new CardEvent("E2", "SAV2001", new BigDecimal("800"), 10),    // SAME window, earlier time
            new CardEvent("E3", "SAV2001", new BigDecimal("500"), 95),    // window 60-120, advances watermark
            new CardEvent("E4", "SAV2001", new BigDecimal("300"), 45)     // late straggler for window 0-60
        );

        log.info("=== RUN 1 (out-of-order + late straggler) ===");
        EventTimeWindower w = new EventTimeWindower(60, 5, 30, store);
        arrival.forEach(w::process);
        w.flush();
        log.info("Store size after run 1 = " + store.size());

        log.info("=== REPLAY (reprocessing, must be idempotent) ===");
        EventTimeWindower w2 = new EventTimeWindower(60, 5, 30, store);
        arrival.forEach(w2::process);
        w2.flush();
        log.info("Store size after replay = " + store.size());
    }
}
